INSERT INTO "public"."biz_message" VALUES (8, 3, 'USER', '{"text": "玉米种植方案"}', NULL, NULL, 'f', 1, '2026-09-18 17:03:11.139', 1, '2026-09-18 17:03:11.139');
INSERT INTO "public"."biz_message" VALUES (9, 3, 'AI', '{"text": "以下是根据农业知识库整理的**玉米高产种植方案**，涵盖播种、施肥、密度及常见问题应对等关键环节：\n\n---\n\n### 一、播种要求\n- **温度条件**：地温稳定 ≥12°C 时可播种；适宜发芽温度为 22–30°C，苗期可短时耐受 5–8°C 低温。\n- **土壤含水率**：最佳维持在 60%–70%，确保种子萌发所需水分，提高出苗率。\n- **播种深度**：\n  - 墒情较好地块：3–4 cm；\n  - 干旱地块：适当加深至 5–6 cm（**不可超过 7 cm**），避免影响出苗速度与整齐度。\n\n- **播种时间**：\n  - 华南地区：春玉米 2–3 月，秋玉米 7–8 月；\n  - 其他地区依当地气候调整。\n\n---\n\n### 二、种植密度\n- 普通大田：**4000–4500 株/亩**\n- 耐密型品种：可提升至 **4800–5200 株/亩**\n\n> 密度过大会导致空秆、光照不足等问题，需结合土壤肥力和品种特性合理调控。\n\n---\n\n### 三、科学施肥方案（三阶段）\n| 阶段 | 时间节点 | 施肥内容 | 目的 |\n|------|----------|-----------|------|\n| **基肥** | 播种前 | 腐熟农家肥 2000–2500 kg/亩 + 复合肥（15-15-15）30–40 kg | 培肥地力，促进根系发育 |\n| **拔节肥** | 展叶 6–8 片时 | 尿素 15–20 kg/亩 | 促进茎叶快速生长，增强光合能力 |\n| **穗肥** | 大喇叭口期（雌穗分化关键期） | 尿素 20–25 kg + 钾肥 8–10 kg/亩 | 促进雌穗发育，减少秃尖，提高结实率 |\n\n> ⚠️ 注意：大喇叭口期是决定果穗大小和籽粒数量的关键窗口期，此时营养需求达到峰值，应确保及时足量追肥。\n\n---\n\n### 四、常见问题与应对措施\n| 问题 | 原因 | 应对措施 |\n|------|------|-----------|\n| **秃尖缺粒** | 高温干旱、授粉遇雨或养分失衡 | 合理灌溉；补施钾肥；必要时人工辅助授粉 |\n| **空秆现象** | 密度过大、光照不足或土壤贫瘠 | 控制密度（每亩 3500–4500 株）；增施磷钾肥 |\n\n---\n\n如您有具体区域（如华北、西南）、品种类型（如甜糯玉米、高产籽粒玉米）或特殊需求（如节水栽培、有机种植），我可进一步细化方案。需要吗？"}', NULL, NULL, 'f', 1, '2026-09-18 17:03:18.264', 1, '2026-09-18 17:03:18.264');
