INSERT INTO "public"."biz_message" VALUES (12, 3, 'USER', '{"text": "土豆种植方案"}', NULL, NULL, 'f', 1, '2026-09-18 17:03:40.503', 1, '2026-09-18 17:03:40.503');
INSERT INTO "public"."biz_message" VALUES (13, 3, 'AI', '{"text": "根据当前知识库中没有找到“土豆种植方案”的具体资料，我将基于我的农业知识为您提供一个通用的土豆（马铃薯）种植方案，供参考：\n\n---\n\n### 🌱 土豆种植方案（通用版）\n\n#### 一、品种选择\n- 根据当地气候和市场需求选择早熟、中熟或晚熟品种。\n- 常见品种：''费乌瑞它''（早熟）、''克新1号''（高产抗病）、''冀张薯8号''（适合北方）等。\n\n#### 二、整地与施肥\n- **整地**：深耕25–30 cm，清除杂草、石块，起垄（垄高15–20 cm，垄宽60–70 cm）。\n- **基肥**：每亩施腐熟有机肥2000–3000 kg + 复合肥（如15-15-15）40–50 kg + 钾肥（K₂O）5–10 kg。\n- 注意：避免施用未腐熟农家肥，以防烧根或病害传播。\n\n#### 三、种薯处理\n- **切块催芽**：播种前20–30天进行切块（每块带1–2个芽眼，约30–50 g），用多菌灵或草木灰消毒，置于15–20℃散光处催芽。\n- **种薯消毒**：可用0.1%高锰酸钾溶液浸种10分钟，晾干后播种。\n\n#### 四、播种时间与密度\n- **播种期**：\n  - 春播：地温稳定在8–10℃时（北方一般4月中下旬）；\n  - 夏播：6月上中旬（南方可延至7月）；\n  - 秋播：9月中下旬（需防霜冻）。\n- **密度**：行距60–70 cm，株距20–25 cm，亩保苗4000–5000株。\n\n#### 五、田间管理\n- **出苗后**：及时查苗补缺；中耕除草2–3次，结合培土防倒伏。\n- **追肥**：\n  - 第一次：现蕾期（植株高30 cm左右），追施尿素10–15 kg/亩；\n  - 第二次：块茎膨大期，追施硫酸钾10–15 kg/亩。\n- **水分管理**：保持土壤湿润但不积水；开花期和块茎膨大期需水较多，忌干旱或涝渍。\n\n#### 六、病虫害防治\n- **常见病害**：晚疫病（最严重）、青枯病、环腐病。\n  - 防治措施：选用抗病品种；发病初期喷施代森锰锌、烯酰吗啉等药剂；及时拔除病株。\n- **常见虫害**：蚜虫、蛴螬、二十八星瓢虫。\n  - 防治方法：黄板诱杀蚜虫；地下害虫用辛硫磷颗粒剂拌土撒施。\n\n#### 七、收获与贮藏\n- **收获期**：植株枯黄、块茎表皮木栓化时（通常在终霜后20–30天）。\n- **贮藏条件**：温度2–4℃、湿度85–90%、避光通风，可长期保鲜。\n\n---\n\n如您能提供更具体的地区（如省份/气候带）、种植规模或目标产量，我可以为您定制更精准的方案。是否需要我进一步补充某一部分？"}', NULL, NULL, 'f', 1, '2026-09-18 17:03:47.674', 1, '2026-09-18 17:03:47.674');
