INSERT INTO "public"."biz_message" VALUES (18, 4, 'USER', '{"text": "水稻发黄怎么办"}', NULL, NULL, 'f', 1, '2026-09-18 17:07:56.828', 1, '2026-09-18 17:07:56.828');
INSERT INTO "public"."biz_message" VALUES (19, 4, 'AI', '{"text": "水稻发黄可能是由多种原因引起的，以下是一些常见原因及应对措施，供您参考：\n\n1. **缺氮**：水稻叶片呈均匀淡黄色，老叶先黄，新叶生长缓慢。  \n   ✅ 解决方法：及时追施尿素或复合肥（如每亩5–8公斤尿素），可结合灌溉施用。\n\n2. **缺锌**：新叶出现“白化”或“花叶”，叶尖、叶缘失绿，植株矮小。  \n   ✅ 解决方法：叶面喷施0.1%～0.2%硫酸锌溶液（每亩50–75公斤），或在移栽前基施锌肥。\n\n3. **缺铁**：新叶脉间失绿，呈黄白色网状，严重时整叶变黄甚至枯死。  \n   ✅ 解决方法：叶面喷施0.5%硫酸亚铁+0.2%柠檬酸溶液；也可在水田中施用铁螯合物。\n\n4. **根系受损/积水烂根**：长期淹水或排水不良导致根系缺氧，影响养分吸收。  \n   ✅ 解决方法：及时排水、松土，必要时使用生根剂（如腐殖酸+微生物菌剂）促进恢复。\n\n5. **病害（如稻瘟病、纹枯病）或虫害（如稻飞虱、叶蝉）**：叶片出现斑点、黄化、卷曲等异常症状。  \n   ✅ 解决方法：根据具体病虫害类型选用对症药剂（如三环唑防稻瘟病、噻嗪酮防稻飞虱），并注意轮换用药防止抗性。\n\n建议您先观察水稻发黄的部位（老叶/新叶）、是否伴随斑点/卷曲等其他症状，再结合田间管理情况（如施肥、灌水、病虫发生史）综合判断。若情况严重或难以确定病因，可提供更详细信息（如水稻品种、种植阶段、近期天气等），我可进一步帮您分析。"}', NULL, NULL, 'f', 1, '2026-09-18 17:08:02.645', 1, '2026-09-18 17:08:02.645');
