INSERT INTO "public"."biz_message" VALUES (61, 12, 'AI', '{"text": "根据农业知识库中的《火龙果标准化种植规范》，火龙果从开花到成熟大约需要 **45天**。\n\n如需进一步了解火龙果的种植管理、采收标准等信息，可继续提问。"}', NULL, NULL, 'f', 1, '2026-09-21 17:12:30.252', 1, '2026-09-21 17:12:30.252');
